WITH unpacked AS (SELECT id, log_ts, level, latency_ms, status_code, context['trace'] AS trace, SHIFTRIGHT(status_code, 2) AS status_code_high, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, ROUND(AVG(status_code_high), 2) AS avg_status_code_high, APPROX_PERCENTILE(latency_ms, 0.5) AS latency_ms_p50, SORT_ARRAY(COLLECT_SET(tier)) AS tier_list, COUNT_IF(tier = 'free') AS free_events, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN tier = 'pro' THEN 1 END), 0), 2) AS latency_ms_per_pro FROM unpacked GROUP BY DATE_TRUNC('HOUR', log_ts) HAVING ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN tier = 'pro' THEN 1 END), 0), 2) < 1000000
